export const WORDMARK=Object.freeze({text:"SceneXP.com",height:.024,inset:.03,font:'Impact, "Arial Narrow Bold", "Roboto Condensed", sans-serif',stroke:.09,fill:"#ffffff",outline:"#000000"});export function wordmarkFont(t,o=WORDMARK.font){return`bold ${t}px ${o}`}export function drawWordmark(t,o,n,s={}){const e={...WORDMARK,...s},r=Math.max(1,Math.round(n*e.height)),f=n*e.inset;t.font=wordmarkFont(r,e.font),t.textAlign="right",t.textBaseline="alphabetic",t.lineJoin="round",t.lineWidth=r*e.stroke,t.strokeStyle=e.outline,t.fillStyle=e.fill;const i=o-f,l=n-f;return t.strokeText(e.text,i,l),t.fillText(e.text,i,l),{x:i,y:l,px:r}}
